/**
 * Why a fetch or a sub-flow refused.
 */
public enum SdkError {

    
    
    /**
     * The network refused.
     */
    case Network
    /**
     * The host declined the sub-flow.
     */
    case Declined
    /**
     * The engine's answer was wrong for the request.
     */
    case BadResponse
}


